using System;using System.Reflection;using System.Linq;
class Program{static void Main(){var t=typeof(Uri).Assembly.GetType("System.UriHelper");var method=t.GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Single(m=>m.Name=="UnescapeString"&&m.GetParameters()[0].ParameterType==typeof(string)&&m.GetParameters()[3].ParameterType==typeof(char[]));var modeType=typeof(Uri).Assembly.GetType("System.UnescapeMode");char[][]sets={new[]{'\uffff','\uffff','\uffff'},new[]{'?','#','\uffff'},new[]{'%','/',':'},new[]{'\0','\u007f','\u0080'}};string line;while((line=Console.ReadLine())!=null){var fields=line.Split(' ');int mode=int.Parse(fields[0]),syntax=int.Parse(fields[1]),query=int.Parse(fields[2]),set=int.Parse(fields[3]);string input="";if(fields.Length>4)for(int i=0;i<fields[4].Length;i+=4)input+=(char)Convert.ToUInt16(fields[4].Substring(i,4),16);object parser=syntax==0?new GenericUriParser(GenericUriParserOptions.Default):syntax==1?typeof(UriParser).GetField("FileUri",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null):null;object[]args={input,0,input.Length,new char[input.Length*3+32],0,sets[set][0],sets[set][1],sets[set][2],Enum.ToObject(modeType,mode),parser,query!=0};try{char[]output=(char[])method.Invoke(null,args);Console.WriteLine("S"+string.Concat(output.Take((int)args[4]).Select(c=>((int)c).ToString("x4"))));}catch(TargetInvocationException e){Console.WriteLine("E"+e.InnerException.Message);}}}}
